public class Main {
    static IO io;

    public static void main(String[] args) throws Exception {

        io = new IO("A-small-attempt0");
        int t = io.nextInt();
        for (int i = 0; i < t; i++) {
            io.nextCase();
            solve();
        }
        io.flush();
    }

    public static int[] di = {0,-1,0,1};
    public static int[] dj = {1,0,-1,0};


    public static void solve() {
        int r = io.nextInt();
        int c = io.nextInt();
        char[][] m = io.nextCharMap(r, c);
        boolean[] ck = new boolean[4];
        int ans = 0;
        for(int i=0;i<r;i++) {
            for(int j=0;j<c;j++) {
                if (m[i][j] == '.') {
                    continue;
                }
                for(int k=0;k<4;k++) {
                    ck[k] = check(r,c,m,i,j,di[k],dj[k]);
                }
                if (ck[0] && ck[1] && ck[2] && ck[3]) {
                    io.println("IMPOSSIBLE");
                    return;
                }
                if (ck[0] && m[i][j] == '>' || ck[1] && m[i][j] == '^' || ck[2] && m[i][j] == '<' || ck[3] && m[i][j] == 'v') {
                    ans++;
                }
            }
        }
        io.println(ans);
    }

    public static boolean check(int r,int c,char[][] m,int ni,int nj,int di,int dj) {
        ni += di;
        nj += dj;
        while(0 <= ni && ni < r && 0 <= nj && nj < c) {
            if (m[ni][nj] != '.') {
                return false;
            }
            ni += di;
            nj += dj;
        }
        return true;
    }
 }

