             for (int i = 0; i < c.length; i++) {
                 for (char cdigit = '9'; cdigit >= (i == 0 ? '0' : ans[i - 1]); cdigit--) {
                     Arrays.fill(ans, i, c.length, cdigit);
                     if (Long.parseLong(new String(ans)) <= Long.parseLong(new String(c))) {
                         break;
                     }
                 }
