     private String solve() {
         StringBuilder strb = new StringBuilder();
         for (int i = 0; i <= 2; i++) {
             String ans = f(i);
             if (ans != null)
                 return ans;
         }
         return "IMPOSSIBLE";
     }

     private String f(int start) {
         int[] count = {r, y, b};
         char[] chars = {'R', 'Y', 'B'};
         if (count[start] == 0)
             return null;
         StringBuilder strb = new StringBuilder();
         int curr = start;

         while (true) {

             strb.append(chars[curr]);
             count[curr]--;


             int maxCount = 0;
             int other = -1;
             for (int i = 0; i <= 2; i++)
                 if (i != curr && count[i] > maxCount) {
                     other = i;
                     maxCount = count[i];
                 }
             if (other == -1)
                 if (count[curr] == 0)
                     break;
                 else
                     return null;
             curr = other;
         }

         String result = strb.toString();
         if (result.charAt(0) == result.charAt(result.length() - 1))
             return null;
         return strb.toString();
     }


