                    ok=false;
                    break loop;
                } else {
                    res+=" "+findSomeDivisor(w);
                }
            }
            if (ok){
                log(res);
                znx[cnt]=res;
                cnt++;
            }
            x+=2;
        }
        return znx;
    }


