            int x = in.nextInt();
            int r = in.nextInt();
            int c = in.nextInt();

            boolean possible = (r * c) % x == 0;

            if (possible) {
                if (x == 3) {
                    if ((r == 1) || (c == 1)) {
                        possible = false;
                    }
                } 
                if (x == 4) {
                    if ((r < 4) && (c < 4)) {
                        possible = false;
                    }
                    if ((r <= 2) || (c <= 2)) {
                        possible = false;
                    }
                }
            }

            out.println("Case #" + test + ": " + (possible ? "GABRIEL" : "RICHARD"));

        }
    }
 }
