    int[] dj = { 0, -1, 0, 1 };

    int toDir(char c) {
        if (c == '.')
            return -1;
        if (c == '^')
            return 0;
        if (c == '<')
            return 1;
        if (c == 'v')
            return 2;
        if (c == '>')
            return 3;
        throw new AssertionError();
    }

    public void solve() throws IOException {
        int n = in.nextInt(), m = in.nextInt();
