        for (int i = 0; i < n; i++) {
            c[i] = in.next().toCharArray();
        }
        boolean[][][] is = new boolean[n][m][di.length];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int t = 0; t < di.length; t++) {
                    int ci = i, cj = j;
                    ci += di[t];
                    cj += dj[t];
                    while (ci >= 0 && cj >= 0 && ci < n && cj < m) {
                        if (c[ci][cj] != '.') {
                            is[i][j][t] = true;
                            break;
                        }
                        ci += di[t];
                        cj += dj[t];
                    }
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (c[i][j] != '.') {
                    boolean ok = false;
                    int curT = toDir(c[i][j]);
                    if (is[i][j][curT]) {
                        ok = true;
                    } else {
                        for (int t = 0; t < 4; t++) {
                            if (is[i][j][t]) {
                                ans++;
                                ok = true;
                                break;
                            }
                        }
                    }
                    if (!ok) {
                        out.println("IMPOSSIBLE");
                        return;
                    }
                }
            }
        }
        out.println(ans);
    }

