        for (int i = 0; i < n; i++) {
            e[i] = in.nextLong();
            s[i] = in.nextLong();
        }
        d = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                d[i][j] = in.nextLong();
            }
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (d[i][k] != -1 && d[k][j] != -1) {
                        if (d[i][j] == -1 || d[i][j] > d[i][k] + d[k][j]) {
                            d[i][j] = d[i][k] + d[k][j];
                        }
                    }
                }
            }
        }
        for (int test = 0; test < q; test++) {
            int from = in.nextInt() - 1;
            int to = in.nextInt() - 1;
            double[] dist = new double[n];
            final double inf = Double.POSITIVE_INFINITY;
            Arrays.fill(dist, inf);
            boolean[] was = new boolean[n];
