            while (true) {
                int u = -1;
                for (int i = 0; i < n; i++) {
                    if (!was[i] && dist[i] != inf) {
                        if (u == -1 || dist[i] < dist[u]) {
                            u = i;
                        }
                    }
                }
                if (u == -1) {
                    break;
                }
                was[u] = true;
                for (int j = 0; j < n; j++) {
                    if (d[u][j] != -1 && e[u] >= d[u][j]) {
                        dist[j] = Math.min(dist[j], dist[u] + d[u][j] * 1.0 / s[u]);
                    }
                }
            }
            out.print(dist[to] + " ");
        }
        out.println();
    }

