public class B {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int res = 0;
            int N = in.nextInt(), C = in.nextInt(), M = in.nextInt();
            int[] P = new int[M];
            int[] B = new int[M];
            for (int i = 0; i < M; i++) {
                P[i] = in.nextInt();
                B[i] = in.nextInt();
            }
            if (C != 2) continue;


            int[] cnt = new int[C];
            for (int i = 0; i < M; i++) {
                if (P[i] == 1) {
                    cnt[B[i]-1]++;
                    res++;
                }
            }

            int x = 0;
            int[] cnt2 = new int[2];
            for (int i = 0; i < M; i++) {
                if (P[i] != 1) {
                    int id = (B[i] - 1) ^ 1;
                    if (cnt[id] == 0) 
                        cnt2[id]++;
                    else { 
                        cnt[id]--;
                        x++;
                    }
                }
            }
            res += Math.max(cnt2[0], cnt2[1]);

            int[][] cnt3 = new int[2][N+1];
            for (int i = 0; i < M; i++) {
                if (P[i] != 1) {
                    cnt3[B[i]-1][P[i]]++;
                }
            }

            int promoted = 0;
            for (int i = 0; i < N+1; i++) {
                promoted = Math.max(promoted, cnt3[0][i] + cnt3[1][i] - x - Math.max(cnt2[0], cnt2[1]));
            }
            out.println("Case #" + caseN + ": " + res + " " + promoted);
        }
        out.close();
    }

