        int start;
        int end;
        Activity(int start, int duration) {
            this.start = start;
            this.end = duration;
        }
    }

    ArrayList<Activity> C, J;

    private void readCase(final Scanner in) {
        Ac = in.nextInt();
        Aj = in.nextInt();

        C = new ArrayList<>();
        J = new ArrayList<>();

        for (int i = 0; i < Ac; i++) {
            C.add(new Activity(in.nextInt(), in.nextInt()));
        }
        for (int i = 0; i < Aj; i++) {
            J.add(new Activity(in.nextInt(), in.nextInt()));
