                 for (int j = i; j < cnt.length; j += 1) {
                     if (cnt[j] > cnt[best]) {
                         best = j;
                     }
                 }
                 if (best > i) {
                     int cc = cnt[i];
                     int ii = inds[i];
                     cnt[i] = cnt[best];
                     inds[i] = inds[best];
                     cnt[best] = cc;
                     inds[best] = ii;
                 }
             }
             int[] answer = new int[N];
             int ind = 0;
             for (int i = 0; i < N; i += 2) {
                 cnt[ind] -= 1;
                 answer[i] = inds[ind];
                 if (cnt[ind] == 0) ind += 1;
             }
             for (int i = 1; i < N; i += 2) {
                 cnt[ind] -= 1;
                 answer[i] = inds[ind];
                 if (cnt[ind] == 0) ind += 1;
             }
             StringBuffer sb = new StringBuffer();
             for (int i = 0; i < N; i += 1) {
                 sb.append(str.charAt(answer[i]));
             }
             out.println(sb.toString());
         }

