    static String INPUT = "";

    int hd, ad, b, d;
    int hk, ak;

    public void read() 
    {
        hd = ni(); ad = ni();
        hk = ni(); ak = ni();
        b = ni(); d = ni();
    }


    int[][] dp;
    int I = Integer.MAX_VALUE;

    public void process() 
    {
        dp = new int[101][101];
        for(int i = 0;i < 101;i++){
            Arrays.fill(dp[i], I);
        }


        int min = I;
        for(int i = 0;i <= 100;i++){
            for(int j = 0;j <= 100;j++){
                int res = simulate(i, j);

                min = Math.min(min, res);
            }
        }
        if(min == I){
            out.println("IMPOSSIBLE");
        }else{
            out.println(min);
        }
    }

    public int simulate(int nb, int nd)
    {
        if(d == 0 && nd > 0)return I;
        if(b == 0 && nb > 0)return I;

        int step = 0;
        int lhd = hd, lad = ad;
        int lak = ak, lhk = hk;
        for(int i = 0;i < nd;i++){
            int nlak = Math.max(0, lak-d);
            if(lhd - nlak <= 0){
                if(lhd == hd)return I;
                step++; lhd = hd - lak;
                if(lhd - nlak <= 0)return I;
            }
            lak = nlak;
            lhd -= lak;
            step++;
        }
        for(int i = 0;i < nb;i++){
            lad += b;
            if(lhd - lak <= 0){
                if(lhd == hd)return I;
                step++; lhd = hd - lak;
                if(lhd - lak <= 0)return I; 
            }
            lhd -= lak;
            step++;
        }

        long code = (long)lhd<<32|lhk;
        while(true){
            if(lhk - lad > 0 && lhd - lak <= 0){
                if(lhd == hd)return I;
                step++; lhd = hd;
                lhd -= lak;
            }else{
                lhk -= lad;
                step++;
                if(lhk <= 0)return step;
                lhd -= lak;
            }
            long ncode = (long)lhd<<32|lhk;
            if(code == ncode)return I;
            code = ncode;
        }
    }

