        int R = in.readInt(),
            C = in.readInt();
        int[]sol = new int[]{0,0,1,2,1,1,2};











        if(R <= 6){
            if(C == 3){
                if(R==2){
                    out.printLine(sol[R]+3);
                }else if(R==4){
                    out.printLine(sol[R]+6);                    
                }else if(R==5){
                    out.printLine(sol[R]+6);                    
                }else if(R==6){
                    out.printLine(sol[R]+12); 
                }else{
                    out.printLine(sol[R]); 
                }               
            }
            else if(C == 4){
                if(R==3){
                    out.printLine(sol[R]+4); 
                }else if(R==5){
                    out.printLine(sol[R]+8);
                }else if(R==6){
                    out.printLine(sol[R]+8);                    
                }else{
                    out.printLine(sol[R]); 
