 class TaskB {
     public void solve(int testNumber, InputReader in, PrintWriter out) {
         int B = in.nextInt();
         int N = in.nextInt();
         int M[] = new int[B];
         for (int i = 0; i < B; i++) {
             M[i] = in.nextInt();
         }

         long lo = 0, hi = 10L * Integer.MAX_VALUE;

         while (lo + 1 < hi) {
             long mid = (lo + hi) >> 1;
             if (value(mid, M) >= N) {
                 hi = mid;
             } else {
                 lo = mid;
             }
         }

         long val = value(hi, M);
         int ans = 0;
         for (int i = M.length - 1; i >= 0; i--) {
             if (hi % M[i] == 0) {
                 if (val == N){
                     out.println("Case #" + testNumber + ": " + (i + 1));
                     return;
                 }
                 val--;
             }
         }
         out.println("Case #" + testNumber + ": " + (M.length));
         return;
     }

     private long value(long mid, int[] m) {
         long ans = 0;
         for (int i = 0; i < m.length; i++) {
             ans += (mid+1) / m[i];
             if ((mid+1) % m[i] > 0) ans++;
         }
         return ans;
     }
 }

