        int func(int x) {
            int ans = 0;
            while(x != 0) {


                int bit = 0;
                while((x >>> bit & 1) == 0) {
                    bit++;
                }
                if(bit > 0) {
                    ans++;
                    x |= (1 << bit) - 1;

                }
                int len = 1 + Integer.numberOfTrailingZeros(Integer.highestOneBit(x));
                x = flip(x, len);
                ans++;
            }
            return ans;
        }

        int flip(int x, int len) {
            int y = x & (~0 << len);
            for(int i = 0; i < len; i++) {
                y |= ((x >>> (len - 1 - i) & 1) ^ 1) << i;
            }
            return y;
        }

