        int[] idx;
        boolean[] used;
        boolean ok(int skip) {
            if(skip != 0 && skip != 1) return false;

            Arrays.fill(used, false);
            for(int i = 0; i < n; i++) {
                if(idx[i] != -1) {
                    used[idx[i]] = true;
                }
            }
            for(int i = 1, j = 1; j < n && i < 2*n-1; i++) {
                if(used[i]) continue;
                boolean ok = true;
                for(int x = 0; x < n; x++) {
                    if(idx[x] != -1 && xs[i][x] != xs[idx[x]][j]) {
                        ok = false;
                        break;
                    }
                }
                if(!ok) {
                    if(skip == 0) return false;
                    skip--;
                    i--;
                }
                j++;
            }
            return true;
        }



