        final int[] KEY;

        public ArrayIntsComparator(int... key) {
            KEY = key;
        }

        @Override
        public int compare(int[] o1, int[] o2) {
            for(int k : KEY) if(o1[k] != o2[k]) return o1[k] - o2[k];
