    static class ArrayIntComparator implements Comparator<int[]> {
        final int KEY;

        public ArrayIntComparator(int key) {
            KEY = key;
        }

        @Override
        public int compare(int[] o1, int[] o2) {
            return o1[KEY] - o2[KEY];
        }
    }


