 import static java.lang.Math.min;
 import static java.lang.System.exit;








 public class A {

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;
    static int test;

    static void solve() throws Exception {
        int n = nextInt();
        int d = nextInt();
        int sCur = nextInt();
        int as = nextInt();
        int cs = nextInt();
        int rs = nextInt();
        int mCur = nextInt();
        int am = nextInt();
        int cm = nextInt();
        int rm = nextInt();
        int min[] = new int[n];
        int max[] = new int[n];
        min[0] = sCur - d;
        max[0] = sCur + 1;
        for (int i = 1; i < n; i++) {
            sCur = (int) (((long) sCur * as + cs) % rs);
            mCur = (int) (((long) mCur * am + cm) % rm);
            min[i] = max(min[mCur % i], sCur - d);
            max[i] = min(max[mCur % i], sCur + 1);

        }
        int change[] = new int[rs + 1];
        for (int i = 0; i < n; i++) {
            if (min[i] < max[i]) {
                ++change[max(min[i], 0)];
                --change[max[i]];
            }
        }
        int ans = 0;
        int cans = 0;
        for (int i = 0; i <= rs; i++) {
            cans += change[i];
            ans = max(ans, cans);
        }
        printCase();
        out.println(ans);
    }

