 class MyMath {
     public static long sqrt(long n) {
    long right=3037000499L;
    long left=1;
    if (n>right*right) {
        return -(right+1)-1;
    }
    if (n==0) {
        return 0;
    }
    if (n==1) {
        return 1;
    }
    if (n<0) {
        return -1;
    }
    if (n/2 < right) {
        right = n/2;
    }
    while (left<=right) {
        long m = (left+right)/2;
        long m2 = m*m;
        if (m2 == n) {
        return m;
        }
        if (m2 < n) {
        left=m+1;
        } else {
        right=m-1;
        }
    }
    return -(left)-1;
     }
 }

 class Point implements Comparable<Point> {
     public int x;
     public int y;

     public Point(int X,int Y) {
    this.x = X;
    this.y = Y;
     }

     public Point() {
    this.x=0;
    this.y=0;
     }


     public int compareTo(Point other)     
     {
    if( x == other.x) {
        if (y > other.y) {
        return 1;
        } else if (y<other.y) {
        return -1;
        }
        return 0;
    } else {
        if (x > other.x) {
        return 1;
        } else if (x<other.x) {
        return -1;
        }
        return 0;
    }
     }

     public boolean equals(Object po) {
    if (!(po instanceof Point)) {
        return false;
    }
    Point p = (Point)(po);
    return (p.x==x) && (p.y==y);
     }


     public double exterior( Point p)
     {
    return x * p.y - y * p.x;
     }

     public Point add( Point p)
     {
    return new Point( x + p.x, y + p.y );
     }


     public Point subtract( Point p)
     {
    return new Point( x - p.x, y - p.y );
     }

     public double distance(Point b) {
    return Math.hypot(x-b.x, y-b.y);
     }

     public String toString()
     {
    StringBuffer sb = new StringBuffer();
    sb.append("Point[x=");
    sb.append(x);
    sb.append(",y=");
    sb.append(y);
    sb.append("]");
    return sb.toString();
     }
 }

 class Ominoes {
     public ArrayList<Point> points;

     public Ominoes() {
    points = new ArrayList<Point>();
     }

     public Ominoes(Ominoes o) {
    points = new ArrayList<Point>(o.points.size());
    for (int i=0; i<o.points.size(); i++) {
        Point p1 = o.points.get(i);
        points.add(new Point(p1.x, p1.y));
    }
     }

     public int getN() {
    return points.size();
     }

     public void shift() {
    int minX=Integer.MAX_VALUE;
    int minY=Integer.MAX_VALUE;
    for (Point p : points) {
        if (p.x < minX) {
        minX = p.x;
        }
        if (p.y < minY) {
        minY = p.y;
        }
    }
    for (int i=0; i<points.size(); i++) {
        Point p = points.get(i);
        Point np = new Point(p.x-minX, p.y-minY);
        points.set(i,np);
    }
    Collections.sort(points);
     }

     public void flip() {
    shift();
    for (int i=0; i<points.size(); i++) {
        Point p = points.get(i);
        Point np = new Point(-p.x, p.y);
        points.set(i,np);
    }
    shift();
     }

     public void turn() {
    shift();
    for (int i=0; i<points.size(); i++) {
        Point p = points.get(i);
        Point np = new Point(-p.y, p.x);
        points.set(i,np);
    }
    shift();
     }

     public boolean equals(Ominoes o) {
    if (o.getN() != getN()) {
        return false;
    }
    for (int i=0; i<points.size(); i++) {
        Point p1 = points.get(i);
        Point p2 = o.points.get(i);
        if (p1.compareTo(p2) != 0) {
        return false;
        }
    }
    return true;
     }

     public boolean equalsIgnoreDirection(Ominoes o) {
    shift();
    boolean ret=false;
    for (int i=0; i<2; i++) {
        for (int j=0; j<4; j++) {
        if (!ret && this.equals(o)) {
            ret = true;
        }
        this.turn();
        }
        this.flip();
    }
    return ret;
     }

     public String toString() {
    StringBuffer sb = new StringBuffer();
    sb.append("Ominoes[points=[");
    for (int i=0; i<points.size(); i++) {
        if (i>0) {
        sb.append(",");
        }
        sb.append(points.get(i).toString());
    }
    sb.append("]]");
    return sb.toString();
     }

     public int getWidth() {
    int maxX=0;
    int maxY=0;
    for (Point p : points) {
        if (p.x > maxX) {
        maxX = p.x;
        }
        if (p.y > maxY) {
        maxY = p.y;
        }
    }
    return maxX+1;
     }
     public int getHeight() {
    int maxX=0;
    int maxY=0;
    for (Point p : points) {
        if (p.x > maxX) {
        maxX = p.x;
        }
        if (p.y > maxY) {
        maxY = p.y;
        }
    }
    return maxY+1;
     }

     public String print1() {
    shift();
    int maxX=0;
    int maxY=0;
    for (Point p : points) {
        if (p.x > maxX) {
        maxX = p.x;
        }
        if (p.y > maxY) {
        maxY = p.y;
        }
    }
    StringBuffer sb = new StringBuffer();
    for (int i=0; i<=maxY; i++) {
        for (int j=0; j<=maxX; j++) {
        Point p1 = new Point(j,i);
        if (points.contains(p1)) {
            sb.append("#");
        } else {
            sb.append(" ");
        }
        }
        sb.append(String.format("%n"));
    }
    return sb.toString();
     }

 }
