        while (act <= c.length() - k) {
            if (c.charAt(act) == '-') {
                result++;
                int roz = 0;
                for (int i = act; i < act + k; i++) {
                    if (c.charAt(i) == '-') {
                        d = c.substring(0, i) + "+" + c.substring(i + 1);
                        roz++;
                    } else {
                        d = c.substring(0, i) + "-" + c.substring(i + 1);
                        roz--;
                    }
                    c = d;
                }




            }
            act++;
        }
        for (int i  = 0; i < c.length(); i++) {
            if (c.charAt(i) == '-') {
                return "Case #"+ index +": " + impossible;
            }
        }
        return "Case #"+ index +": " + result;
    }
 }
