import static java.lang.Math.*;
 import static java.lang.Integer.*;

 public class B {
    static Scanner sc = null;
    static BufferedReader br = null;
    static PrintWriter out = null;
    static PrintStream sysout = System.out;
    static Random rnd = new Random();

    int INF = Integer.MAX_VALUE / 10;
    double DF = 0.0000000001;

    long b = 1;
    int N = 0;
    int M = 0;

    String IMP = "IMPOSSIBLE";

    public void solve() throws Exception{
        String s = br.readLine();

        String[] sp = s.split(" ");
        N = Integer.parseInt(sp[0]);
        double V = Double.parseDouble(sp[1]);
        double X = Double.parseDouble(sp[2]);
        if(N == 1){
            s = br.readLine();
            sp = s.split(" ");
            double r = Double.parseDouble(sp[0]);
            double c = Double.parseDouble(sp[1]);
            if(Math.abs(c - X) > DF){
                println(IMP);
            }
            else{
                double ans = V / r;
                println(ans);
            }
        }
        else{
            s = br.readLine();
            sp = s.split(" ");
            double r1 = Double.parseDouble(sp[0]);
            double c1 = Double.parseDouble(sp[1]);
            s = br.readLine();
            sp = s.split(" ");
            double r2 = Double.parseDouble(sp[0]);
            double c2 = Double.parseDouble(sp[1]);
            if(same(c1, c2)){
                if(same(c1, X)){
                    double r = r1 + r2;
                    double ans = V / r;
                    println(ans);
                }
                else{
                    println(IMP);
                }
            }
            else{
                if(same(c1, X)){
                    double ans = V / r1;
                    println(ans);
                }
                else if(same(c2, X)){
                    double ans = V / r2;
                    println(ans);
                }
                else{
                    if(c1 < X && c2 < X){
                        println(IMP);
                    }
                    else if(c1 > X && c2 > X){
                        println(IMP);
                    }
                    else{
                        double d1 = Math.abs(c1 - X);
                        double d2 = Math.abs(c2 - X);
                        double totaldiff = d1 + d2;
                        double ans = 0;
                        double v1 = V * d2 / totaldiff;
                        double a1 = v1 / r1;
