                        if(eng.contains(sp[j])){
                            eng.remove(sp[j]);
                            amb.add(sp[j]);
                        }
                        else if(!amb.contains(sp[j])){
                            fre.add(sp[j]);
                        }
                    }   
                }
            }
            ans = Math.min(ans, amb.size());
        }
        else{
            check(bs, idx+1);
            bs[idx] = true;
            check(bs, idx+1);
