         if (X>maxT || X<minT) {
             out.printf("Case #%d: %s\n", caseNumber, NO);
             return;
         }

         if (N==1) {
             if (X!=C[0]) {                
                 out.printf("Case #%d: %s\n", caseNumber, NO);
             } else {
                 out.printf("Case #%d: %s\n", caseNumber, V/R[0]);                
             }
             return;
         }


         double ret = small(V,X,R,C);


         out.printf("Case #%d: %s\n", caseNumber, ret);


     }



     private double small(double V, double deg, double[] R, double[] C) {
         int n = C.length;
         if (n!=2) {
             return -1;
         }

         double ret = 1e10;
         if (deg==C[0] && deg==C[1]) {
             ret = V/(R[0]+R[1]);
         } else if (deg==C[0]) {
             ret = V/R[0];            
         } else if (deg==C[1]) {
             ret = V/R[1];
         } else {


             double V0=((C[1]-deg)*V)/(C[1]-C[0]), V1=-((C[0]-deg)*V)/(C[1]-C[0]);
             ret = max(V0/R[0],V1/R[1]);
         }

         return ret;
     }


     public static double[] gauss(double[][] a, double[] b) {
         final double EPS = 1e-11;

         double[] x = new double[a[0].length];

         int row = 0;
         for (int i = 0; i < a[0].length; ++i) {

             int maxr = row;
             for (int k = row + 1; k < a.length; ++k) {
                 if (abs(a[k][i]) > abs(a[maxr][i])) {
                     maxr = k;
                 }
             }

             if (a[maxr][i] != 0) {
                 if (maxr != row) {

                     double[] ta = a[row];
                     a[row] = a[maxr];
                     a[maxr] = ta;

                     double tb = b[row];
                     b[row] = b[maxr];
                     b[maxr] = tb;
                 }

                 for (int k = row + 1; k < a.length; ++k) {
                     if (a[k][i] != 0) {
                         double mul = -a[k][i] / a[row][i];
                         a[k][i] = 0; 
                         for (int l = i + 1; l < a[0].length; ++l) {
                             a[k][l] += mul * a[row][l];
                         }
                         b[k] += mul * b[row];
                     }
                 }
                 row++;
             }
         }


         for (int i = a.length - 1; i >= 0; i--) {

             int j = 0;

             while (j < a[i].length && abs(a[i][j]) < EPS)
                 j++;

             if (j < a[i].length) {

                 x[j] = b[i];
                 for (int k = a[0].length - 1; k >= j + 1; k--) {
                     if (x[k] != 0 && a[i][k] != 0) 
                         x[j] -= a[i][k] * x[k];
                 }
                 x[j] /= a[i][j];
             } else if (abs(b[i]) > EPS) {

                 return null; 
             }
         }
         return x;
     }

