public class Main {
     public static void main(String[] args) {
         Locale.setDefault(Locale.US);
         InputStream inputStream;
         try {
             final String regex = "A-(small|large).*[.]in";
             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified()) {
                     toRun = candidate;
                 }
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("a.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskA solver = new TaskA();
         solver.solve(1, in, out);
         out.close();
     }

     static class TaskA {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int n;
                 int k;
                 int[] r;
                 int[] h;


                 public void read(InputReader in) {
                     n = in.readInt();
                     k = in.readInt();
                     r = new int[n];
                     h = new int[n];
                     IOUtils.readIntArrays(in, r, h);
                 }

                 double answer;


                 public void solve() {
                     ArrayUtils.orderBy(r, h);
                     double[] result = new double[k];
                     Arrays.fill(result, Double.NEGATIVE_INFINITY);
                     result[0] = 0;
                     for (int i = 0; i < n; i++) {
                         double side = 2 * r[i] * Math.PI * h[i];
                         answer = Math.max(answer, result[k - 1] + side + r[i] * Math.PI * r[i]);
                         for (int j = k - 2; j >= 0; j--) {
                             result[j + 1] = Math.max(result[j + 1], result[j] + side);
                         }
                     }
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.printLine("Case #" + testNumber + ":", answer);
                 }
             }, 4);
         }

     }

     static class Range {
         public static IntList range(int from, int to) {
             int[] result = new int[Math.abs(from - to)];
             int current = from;
             if (from <= to) {
                 for (int i = 0; i < result.length; i++) {
                     result[i] = current++;
                 }
             } else {
                 for (int i = 0; i < result.length; i++) {
                     result[i] = current--;
                 }
             }
             return new IntArray(result);
         }

     }

     static class IntArray extends IntAbstractStream implements IntList {
         private int[] data;

         public IntArray(int[] arr) {
             data = arr;
         }

         public int size() {
             return data.length;
         }

         public int get(int at) {
             return data[at];
         }

         public void addAt(int index, int value) {
             throw new UnsupportedOperationException();
         }

         public void removeAt(int index) {
             throw new UnsupportedOperationException();
         }

         public void set(int index, int value) {
             data[index] = value;
         }

     }

     static interface IntCollection extends IntStream {
         public int size();

         default public void add(int value) {
             throw new UnsupportedOperationException();
         }

         default public int[] toArray() {
             int size = size();
             int[] array = new int[size];
             int i = 0;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 array[i++] = it.value();
             }
             return array;
         }

         default public IntCollection addAll(IntStream values) {
             for (IntIterator it = values.intIterator(); it.isValid(); it.advance()) {
                 add(it.value());
             }
             return this;
         }

     }

     static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
         public IntIterator intIterator();

         default public Iterator<Integer> iterator() {
             return new Iterator<Integer>() {
                 private IntIterator it = intIterator();

                 public boolean hasNext() {
                     return it.isValid();
                 }

                 public Integer next() {
                     int result = it.value();
                     it.advance();
                     return result;
                 }
             };
         }

         default public int compareTo(IntStream c) {
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 int i = it.value();
                 int j = jt.value();
                 if (i < j) {
                     return -1;
                 } else if (i > j) {
                     return 1;
                 }
                 it.advance();
                 jt.advance();
             }
             if (it.isValid()) {
                 return 1;
             }
             if (jt.isValid()) {
                 return -1;
             }
             return 0;
         }

     }

     static interface IntReversableCollection extends IntCollection {
     }

     static class Scheduler {
         private final AtomicInteger testsRemaining;
         private final AtomicInteger threadsRemaining;

         public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
             try {
                 testsRemaining = new AtomicInteger(in.readInt());
                 threadsRemaining = new AtomicInteger(numParallel);
                 Task[] tasks = new Task[testsRemaining.get()];
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i] = factory.newTask();
                 }
                 for (Task task : tasks) {
                     task.read(in);
                     new Thread(() -> {
                         boolean freeThread = false;
                         synchronized (this) {
                             do {
                                 try {
                                     wait(10);
                                 } catch (InterruptedException ignored) {
                                 }
                                 if (threadsRemaining.get() != 0) {
                                     synchronized (threadsRemaining) {
                                         if (threadsRemaining.get() != 0) {
                                             threadsRemaining.decrementAndGet();
                                             freeThread = true;
                                         }
                                     }
                                 }
                             } while (!freeThread);
                         }
                         task.solve();
                         System.err.println(testsRemaining.decrementAndGet());
                         threadsRemaining.incrementAndGet();
                     }).start();
                 }
                 synchronized (this) {
                     while (testsRemaining.get() > 0) {
                         wait(10);
                     }
                 }
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i].write(out, i + 1);
                 }
             } catch (InterruptedException e) {
                 throw new RuntimeException(e);
             }
         }

     }

     static interface Task {
         public void read(InputReader in);

         public void solve();

         public void write(OutputWriter out, int testNumber);

     }

     static abstract class IntAbstractStream implements IntStream {

         public String toString() {
             StringBuilder builder = new StringBuilder();
             boolean first = true;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 if (first) {
                     first = false;
                 } else {
                     builder.append(' ');
                 }
                 builder.append(it.value());
             }
             return builder.toString();
         }


         public boolean equals(Object o) {
             if (!(o instanceof IntStream)) {
                 return false;
             }
             IntStream c = (IntStream) o;
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 if (it.value() != jt.value()) {
                     return false;
                 }
                 it.advance();
                 jt.advance();
             }
             return !it.isValid() && !jt.isValid();
         }


         public int hashCode() {
             int result = 0;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 result *= 31;
                 result += it.value();
             }
             return result;
         }

     }

     static class IOUtils {
         public static void readIntArrays(InputReader in, int[]... arrays) {
             for (int i = 0; i < arrays[0].length; i++) {
                 for (int j = 0; j < arrays.length; j++) {
                     arrays[j][i] = in.readInt();
                 }
             }
         }

     }

     static interface TaskFactory {
         public Task newTask();

     }

     static interface IntList extends IntReversableCollection {
         public abstract int get(int index);

         public abstract void set(int index, int value);

         public abstract void addAt(int index, int value);

         public abstract void removeAt(int index);

         default public void swap(int first, int second) {
             if (first == second) {
                 return;
             }
             int temp = get(first);
             set(first, get(second));
             set(second, temp);
         }

         default public IntIterator intIterator() {
             return new IntIterator() {
                 private int at;
                 private boolean removed;

                 public int value() {
                     if (removed) {
                         throw new IllegalStateException();
                     }
                     return get(at);
                 }

                 public boolean advance() {
                     at++;
                     removed = false;
                     return isValid();
                 }

                 public boolean isValid() {
                     return !removed && at < size();
                 }

                 public void remove() {
                     removeAt(at);
                     at--;
                     removed = true;
                 }
             };
         }


         default public void add(int value) {
             addAt(size(), value);
         }

         default public IntList sort(IntComparator comparator) {
             Sorter.sort(this, comparator);
             return this;
         }

         default public IntList subList(final int from, final int to) {
             return new IntList() {
                 private final int shift;
                 private final int size;

                 {
                     if (from < 0 || from > to || to > IntList.this.size()) {
                         throw new IndexOutOfBoundsException("from = " + from + ", to = " + to + ", size = " + size());
                     }
                     shift = from;
                     size = to - from;
                 }

                 public int size() {
                     return size;
                 }

                 public int get(int at) {
                     if (at < 0 || at >= size) {
                         throw new IndexOutOfBoundsException("at = " + at + ", size = " + size());
                     }
                     return IntList.this.get(at + shift);
                 }

                 public void addAt(int index, int value) {
                     throw new UnsupportedOperationException();
                 }

                 public void removeAt(int index) {
                     throw new UnsupportedOperationException();
                 }

                 public void set(int at, int value) {
                     if (at < 0 || at >= size) {
                         throw new IndexOutOfBoundsException("at = " + at + ", size = " + size());
                     }
                     IntList.this.set(at + shift, value);
                 }

                 public IntList compute() {
                     return new IntArrayList(this);
                 }
             };
         }

     }

     static class ArrayUtils {
         public static int[] range(int from, int to) {
             return Range.range(from, to).toArray();
         }

         public static int[] createOrder(int size) {
             return range(0, size);
         }

         public static int[] sort(int[] array, IntComparator comparator) {
             return sort(array, 0, array.length, comparator);
         }

         public static int[] sort(int[] array, int from, int to, IntComparator comparator) {
             if (from == 0 && to == array.length) {
                 new IntArray(array).sort(comparator);
             } else {
                 new IntArray(array).subList(from, to).sort(comparator);
             }
             return array;
         }

         public static int[] order(final int[] array) {
             return sort(createOrder(array.length), new IntComparator() {
                 public int compare(int first, int second) {
                     if (array[first] < array[second]) {
                         return -1;
                     }
                     if (array[first] > array[second]) {
                         return 1;
                     }
                     return 0;
                 }
             });
         }

         public static void orderBy(int[] base, int[]... arrays) {
             int[] order = ArrayUtils.order(base);
             order(order, base);
             for (int[] array : arrays) {
                 order(order, array);
             }
         }

         public static void order(int[] order, int[] array) {
             int[] tempInt = new int[order.length];
             for (int i = 0; i < order.length; i++) {
                 tempInt[i] = array[order[i]];
             }
             System.arraycopy(tempInt, 0, array, 0, array.length);
         }

     }

     static class IntArrayList extends IntAbstractStream implements IntList {
         private int size;
         private int[] data;

         public IntArrayList() {
             this(3);
         }

         public IntArrayList(int capacity) {
             data = new int[capacity];
         }

         public IntArrayList(IntCollection c) {
             this(c.size());
             addAll(c);
         }

         public IntArrayList(IntStream c) {
             this();
             if (c instanceof IntCollection) {
                 ensureCapacity(((IntCollection) c).size());
             }
             addAll(c);
         }

         public IntArrayList(IntArrayList c) {
             size = c.size();
             data = c.data.clone();
         }

         public IntArrayList(int[] arr) {
             size = arr.length;
             data = arr.clone();
         }

         public int size() {
             return size;
         }

         public int get(int at) {
             if (at >= size) {
                 throw new IndexOutOfBoundsException("at = " + at + ", size = " + size);
             }
             return data[at];
         }

         private void ensureCapacity(int capacity) {
             if (data.length >= capacity) {
                 return;
             }
             capacity = Math.max(2 * data.length, capacity);
             data = Arrays.copyOf(data, capacity);
         }

         public void addAt(int index, int value) {
             ensureCapacity(size + 1);
             if (index > size || index < 0) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             if (index != size) {
                 System.arraycopy(data, index, data, index + 1, size - index);
             }
             data[index] = value;
             size++;
         }

         public void removeAt(int index) {
             if (index >= size || index < 0) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             if (index != size - 1) {
                 System.arraycopy(data, index + 1, data, index, size - index - 1);
             }
             size--;
         }

         public void set(int index, int value) {
             if (index >= size) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             data[index] = value;
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private InputReader.SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1) {
                 throw new InputMismatchException();
             }
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0) {
                     return -1;
                 }
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9') {
                     throw new InputMismatchException();
                 }
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public boolean isSpaceChar(int c) {
             if (filter != null) {
                 return filter.isSpaceChar(c);
             }
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public interface SpaceCharFilter {
             public boolean isSpaceChar(int ch);

         }

     }

