     static class TaskA {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int n;
                 int p;
                 int[] g;


                 public void read(InputReader in) {
                     n = in.readInt();
                     p = in.readInt();
                     g = IOUtils.readIntArray(in, n);
                 }

                 int answer = 0;


                 public void solve() {
                     int[] qty = new int[p];
                     for (int i : g) {
                         qty[i % p]++;
                     }
                     if (p == 2) {
                         answer = qty[0] + (qty[1] + 1) / 2;
                     } else if (p == 3) {
                         int mn = Math.min(qty[1], qty[2]);
                         answer = qty[0] + mn + (Math.max(qty[1], qty[2]) - mn + 2) / 3;
                     } else {
                         answer = qty[0] + qty[2] / 2;
                         qty[2] %= 2;
                         int mn = Math.min(qty[1], qty[3]);
                         answer += mn;
                         qty[1] -= mn;
                         qty[3] -= mn;
                         if (qty[2] > 0) {
                             if (qty[1] >= 2) {
                                 qty[1] -= 2;
                                 answer++;
                             } else if (qty[3] >= 2) {
                                 qty[3] -= 2;
                                 answer++;
                             }
                         }
                         answer += (qty[1] + 3) / 4;
                         answer += (qty[3] + 3) / 4;
                     }
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.printLine("Case #" + testNumber + ":", answer);
                 }
             }, 4);
         }

     }

