     static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
         public IntIterator intIterator();

         default public Iterator<Integer> iterator() {
             return new Iterator<Integer>() {
                 private IntIterator it = intIterator();

                 public boolean hasNext() {
                     return it.isValid();
                 }

                 public Integer next() {
                     int result = it.value();
                     it.advance();
                     return result;
                 }
             };
         }

         default public int compareTo(IntStream c) {
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 int i = it.value();
                 int j = jt.value();
                 if (i < j) {
                     return -1;
                 } else if (i > j) {
                     return 1;
                 }
                 it.advance();
                 jt.advance();
             }
             if (it.isValid()) {
                 return 1;
             }
             if (jt.isValid()) {
                 return -1;
             }
             return 0;
         }

     }

     static class Scheduler {
         private final AtomicInteger testsRemaining;
         private final AtomicInteger threadsRemaining;

         public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
             try {
                 testsRemaining = new AtomicInteger(in.readInt());
                 threadsRemaining = new AtomicInteger(numParallel);
                 Task[] tasks = new Task[testsRemaining.get()];
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i] = factory.newTask();
                 }
                 for (Task task : tasks) {
                     task.read(in);
                     new Thread(() -> {
                         boolean freeThread = false;
                         synchronized (this) {
                             do {
                                 try {
                                     wait(10);
                                 } catch (InterruptedException ignored) {
                                 }
                                 if (threadsRemaining.get() != 0) {
                                     synchronized (threadsRemaining) {
                                         if (threadsRemaining.get() != 0) {
                                             threadsRemaining.decrementAndGet();
                                             freeThread = true;
                                         }
                                     }
                                 }
                             } while (!freeThread);
                         }
                         task.solve();
                         System.err.println(testsRemaining.decrementAndGet());
                         threadsRemaining.incrementAndGet();
                     }).start();
                 }
                 synchronized (this) {
                     while (testsRemaining.get() > 0) {
                         wait(10);
                     }
                 }
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i].write(out, i + 1);
                 }
             } catch (InterruptedException e) {
                 throw new RuntimeException(e);
             }
         }

     }

     static class EHashMap<E, V> extends AbstractMap<E, V> {
         private static final int[] shifts = new int[10];
         private int size;
         private EHashMap.HashEntry<E, V>[] data;
         private int capacity;
         private Set<Entry<E, V>> entrySet;

         static {
             Random random = new Random(System.currentTimeMillis());
             for (int i = 0; i < 10; i++) {
                 shifts[i] = 1 + 3 * i + random.nextInt(3);
             }
         }

         public EHashMap() {
             this(4);
         }

         private void setCapacity(int size) {
             capacity = Integer.highestOneBit(4 * size);

             data = new EHashMap.HashEntry[capacity];
         }

         public EHashMap(int maxSize) {
             setCapacity(maxSize);
             entrySet = new AbstractSet<Entry<E, V>>() {

                 public Iterator<Entry<E, V>> iterator() {
                     return new Iterator<Entry<E, V>>() {
                         private EHashMap.HashEntry<E, V> last = null;
                         private EHashMap.HashEntry<E, V> current = null;
                         private EHashMap.HashEntry<E, V> base = null;
                         private int lastIndex = -1;
                         private int index = -1;

                         public boolean hasNext() {
                             if (current == null) {
                                 for (index++; index < capacity; index++) {
                                     if (data[index] != null) {
                                         base = current = data[index];
                                         break;
                                     }
                                 }
                             }
                             return current != null;
                         }

                         public Entry<E, V> next() {
                             if (!hasNext()) {
                                 throw new NoSuchElementException();
                             }
                             last = current;
                             lastIndex = index;
                             current = current.next;
                             if (base.next != last) {
                                 base = base.next;
                             }
                             return last;
                         }

                         public void remove() {
                             if (last == null) {
                                 throw new IllegalStateException();
                             }
                             size--;
                             if (base == last) {
                                 data[lastIndex] = last.next;
                             } else {
                                 base.next = last.next;
                             }
                         }
                     };
                 }


                 public int size() {
                     return size;
                 }
             };
         }

         public EHashMap(Map<E, V> map) {
             this(map.size());
             putAll(map);
         }


         public Set<Entry<E, V>> entrySet() {
             return entrySet;
         }


         public void clear() {
             Arrays.fill(data, null);
             size = 0;
         }

         private int index(Object o) {
             return getHash(o.hashCode()) & (capacity - 1);
         }

         private int getHash(int h) {
             int result = h;
             for (int i : shifts) {
                 result ^= h >>> i;
             }
             return result;
         }


         public V remove(Object o) {
             if (o == null) {
                 return null;
             }
             int index = index(o);
             EHashMap.HashEntry<E, V> current = data[index];
             EHashMap.HashEntry<E, V> last = null;
             while (current != null) {
                 if (current.key.equals(o)) {
                     if (last == null) {
                         data[index] = current.next;
                     } else {
                         last.next = current.next;
                     }
                     size--;
                     return current.value;
                 }
                 last = current;
                 current = current.next;
             }
             return null;
         }


         public V put(E e, V value) {
             if (e == null) {
                 return null;
             }
             int index = index(e);
             EHashMap.HashEntry<E, V> current = data[index];
             if (current != null) {
                 while (true) {
                     if (current.key.equals(e)) {
                         V oldValue = current.value;
                         current.value = value;
                         return oldValue;
                     }
                     if (current.next == null) {
                         break;
                     }
                     current = current.next;
                 }
             }
             if (current == null) {
                 data[index] = new EHashMap.HashEntry<E, V>(e, value);
             } else {
                 current.next = new EHashMap.HashEntry<E, V>(e, value);
             }
             size++;
             if (2 * size > capacity) {
                 EHashMap.HashEntry<E, V>[] oldData = data;
                 setCapacity(size);
                 for (EHashMap.HashEntry<E, V> entry : oldData) {
                     while (entry != null) {
                         EHashMap.HashEntry<E, V> next = entry.next;
                         index = index(entry.key);
                         entry.next = data[index];
                         data[index] = entry;
                         entry = next;
                     }
                 }
             }
             return null;
         }


         public V get(Object o) {
             if (o == null) {
                 return null;
             }
             int index = index(o);
             EHashMap.HashEntry<E, V> current = data[index];
             while (current != null) {
                 if (current.key.equals(o)) {
                     return current.value;
                 }
                 current = current.next;
             }
             return null;
         }


         public boolean containsKey(Object o) {
             if (o == null) {
                 return false;
             }
             int index = index(o);
             EHashMap.HashEntry<E, V> current = data[index];
             while (current != null) {
                 if (current.key.equals(o)) {
                     return true;
                 }
                 current = current.next;
             }
             return false;
         }


         public int size() {
             return size;
         }

         private static class HashEntry<E, V> implements Entry<E, V> {
             private final E key;
             private V value;
             private EHashMap.HashEntry<E, V> next;

             private HashEntry(E key, V value) {
                 this.key = key;
                 this.value = value;
             }

             public E getKey() {
                 return key;
             }

             public V getValue() {
                 return value;
             }

             public V setValue(V value) {
                 V oldValue = this.value;
                 this.value = value;
                 return oldValue;
             }

         }

     }

     static class IntArrayList extends IntAbstractStream implements IntList {
         private int size;
         private int[] data;

         public IntArrayList() {
             this(3);
         }

         public IntArrayList(int capacity) {
             data = new int[capacity];
         }

         public IntArrayList(IntCollection c) {
             this(c.size());
             addAll(c);
         }

         public IntArrayList(IntStream c) {
             this();
             if (c instanceof IntCollection) {
                 ensureCapacity(((IntCollection) c).size());
             }
             addAll(c);
         }

         public IntArrayList(IntArrayList c) {
             size = c.size();
             data = c.data.clone();
         }

         public IntArrayList(int[] arr) {
             size = arr.length;
             data = arr.clone();
         }

         public int size() {
             return size;
         }

         public int get(int at) {
             if (at >= size) {
                 throw new IndexOutOfBoundsException("at = " + at + ", size = " + size);
             }
             return data[at];
         }

         private void ensureCapacity(int capacity) {
             if (data.length >= capacity) {
                 return;
             }
             capacity = Math.max(2 * data.length, capacity);
             data = Arrays.copyOf(data, capacity);
         }

         public void addAt(int index, int value) {
             ensureCapacity(size + 1);
             if (index > size || index < 0) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             if (index != size) {
                 System.arraycopy(data, index, data, index + 1, size - index);
             }
             data[index] = value;
             size++;
         }

         public void removeAt(int index) {
             if (index >= size || index < 0) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             if (index != size - 1) {
                 System.arraycopy(data, index + 1, data, index, size - index - 1);
             }
             size--;
         }

     }

     static class IntIntPair implements Comparable<IntIntPair> {
         public final int first;
         public final int second;

         public IntIntPair(int first, int second) {
             this.first = first;
             this.second = second;
         }


         public boolean equals(Object o) {
             if (this == o) {
                 return true;
             }
             if (o == null || getClass() != o.getClass()) {
                 return false;
             }

             IntIntPair pair = (IntIntPair) o;

             return first == pair.first && second == pair.second;
         }


         public int hashCode() {
             int result = first;
             result = 31 * result + second;
             return result;
         }


         public String toString() {
             return "(" + first + "," + second + ")";
         }

         @SuppressWarnings({"unchecked"})
         public int compareTo(IntIntPair o) {
             int value = Integer.compare(first, o.first);
             if (value != 0) {
                 return value;
             }
             return Integer.compare(second, o.second);
         }

     }

