         }

     }

     static class Graph {
         public static final int REMOVED_BIT = 0;
         protected int vertexCount;
         protected int edgeCount;
         private int[] firstOutbound;
         private int[] firstInbound;
         private Edge[] edges;
         private int[] nextInbound;
         private int[] nextOutbound;
         private int[] from;
         private int[] to;
         private long[] weight;
         public long[] capacity;
         private int[] reverseEdge;
         private int[] flags;

         public Graph(int vertexCount) {
             this(vertexCount, vertexCount);
         }

         public Graph(int vertexCount, int edgeCapacity) {
             this.vertexCount = vertexCount;
             firstOutbound = new int[vertexCount];
             Arrays.fill(firstOutbound, -1);

             from = new int[edgeCapacity];
             to = new int[edgeCapacity];
             nextOutbound = new int[edgeCapacity];
             flags = new int[edgeCapacity];
         }

         public int addEdge(int fromID, int toID, long weight, long capacity, int reverseEdge) {
             ensureEdgeCapacity(edgeCount + 1);
             if (firstOutbound[fromID] != -1) {
                 nextOutbound[edgeCount] = firstOutbound[fromID];
             } else {
                 nextOutbound[edgeCount] = -1;
             }
             firstOutbound[fromID] = edgeCount;
             if (firstInbound != null) {
                 if (firstInbound[toID] != -1) {
                     nextInbound[edgeCount] = firstInbound[toID];
                 } else {
                     nextInbound[edgeCount] = -1;
                 }
                 firstInbound[toID] = edgeCount;
             }
             this.from[edgeCount] = fromID;
             this.to[edgeCount] = toID;
             if (capacity != 0) {
                 if (this.capacity == null) {
                     this.capacity = new long[from.length];
                 }
                 this.capacity[edgeCount] = capacity;
             }
             if (weight != 0) {
                 if (this.weight == null) {
                     this.weight = new long[from.length];
                 }
                 this.weight[edgeCount] = weight;
             }
             if (reverseEdge != -1) {
                 if (this.reverseEdge == null) {
                     this.reverseEdge = new int[from.length];
                     Arrays.fill(this.reverseEdge, 0, edgeCount, -1);
                 }
                 this.reverseEdge[edgeCount] = reverseEdge;
             }
             if (edges != null) {
                 edges[edgeCount] = createEdge(edgeCount);
             }
             return edgeCount++;
         }

         protected final GraphEdge createEdge(int id) {
             return new GraphEdge(id);
         }

         public final int addFlowWeightedEdge(int from, int to, long weight, long capacity) {
             if (capacity == 0) {
                 return addEdge(from, to, weight, 0, -1);
             } else {
                 int lastEdgeCount = edgeCount;
                 addEdge(to, from, -weight, 0, lastEdgeCount + entriesPerEdge());
                 return addEdge(from, to, weight, capacity, lastEdgeCount);
             }
         }

         protected int entriesPerEdge() {
             return 1;
         }

         public final int addWeightedEdge(int from, int to, long weight) {
             return addFlowWeightedEdge(from, to, weight, 0);
         }

         public final int addSimpleEdge(int from, int to) {
             return addWeightedEdge(from, to, 0);
         }

         public final int vertexCount() {
             return vertexCount;
         }

         public final int firstOutbound(int vertex) {
             int id = firstOutbound[vertex];
             while (id != -1 && isRemoved(id)) {
                 id = nextOutbound[id];
             }
             return id;
         }

         public final int nextOutbound(int id) {
             id = nextOutbound[id];
             while (id != -1 && isRemoved(id)) {
                 id = nextOutbound[id];
             }
             return id;
         }

         public final int firstInbound(int vertex) {
             initInbound();
             int id = firstInbound[vertex];
             while (id != -1 && isRemoved(id)) {
                 id = nextInbound[id];
             }
             return id;
         }

         public final int nextInbound(int id) {
             initInbound();
             id = nextInbound[id];
             while (id != -1 && isRemoved(id)) {
                 id = nextInbound[id];
             }
             return id;
         }

         public final int source(int id) {
             return from[id];
         }

         public final int destination(int id) {
             return to[id];
         }

         public final void addVertices(int count) {
             ensureVertexCapacity(vertexCount + count);
             Arrays.fill(firstOutbound, vertexCount, vertexCount + count, -1);
             if (firstInbound != null) {
                 Arrays.fill(firstInbound, vertexCount, vertexCount + count, -1);
             }
             vertexCount += count;
         }

         private void initInbound() {
             if (firstInbound == null) {
                 firstInbound = new int[firstOutbound.length];
                 Arrays.fill(firstInbound, 0, vertexCount, -1);
                 nextInbound = new int[from.length];
                 for (int i = 0; i < edgeCount; i++) {
                     nextInbound[i] = firstInbound[to[i]];
                     firstInbound[to[i]] = i;
                 }
             }
         }

         public final boolean flag(int id, int bit) {
             return (flags[id] >> bit & 1) != 0;
         }

         public final boolean isRemoved(int id) {
             return flag(id, REMOVED_BIT);
         }

         protected void ensureEdgeCapacity(int size) {
             if (from.length < size) {
                 int newSize = Math.max(size, 2 * from.length);
                 if (edges != null) {
                     edges = resize(edges, newSize);
                 }
                 from = resize(from, newSize);
                 to = resize(to, newSize);
                 nextOutbound = resize(nextOutbound, newSize);
                 if (nextInbound != null) {
                     nextInbound = resize(nextInbound, newSize);
                 }
                 if (weight != null) {
                     weight = resize(weight, newSize);
                 }
                 if (capacity != null) {
                     capacity = resize(capacity, newSize);
                 }
                 if (reverseEdge != null) {
                     reverseEdge = resize(reverseEdge, newSize);
                 }
                 flags = resize(flags, newSize);
             }
         }

         private void ensureVertexCapacity(int size) {
             if (firstOutbound.length < size) {
                 int newSize = Math.max(size, 2 * from.length);
                 firstOutbound = resize(firstOutbound, newSize);
                 if (firstInbound != null) {
                     firstInbound = resize(firstInbound, newSize);
                 }
             }
         }

         protected final int[] resize(int[] array, int size) {
             int[] newArray = new int[size];
             System.arraycopy(array, 0, newArray, 0, array.length);
             return newArray;
         }

         private long[] resize(long[] array, int size) {
             long[] newArray = new long[size];
             System.arraycopy(array, 0, newArray, 0, array.length);
             return newArray;
         }

         private Edge[] resize(Edge[] array, int size) {
             Edge[] newArray = new Edge[size];
             System.arraycopy(array, 0, newArray, 0, array.length);
             return newArray;
         }

         protected class GraphEdge implements Edge {
             protected int id;

             protected GraphEdge(int id) {
                 this.id = id;
             }

         }

     }

     static interface IntCollection extends IntStream {
         public int size();

         default public void add(int value) {
             throw new UnsupportedOperationException();
         }

         default public int[] toArray() {
             int size = size();
             int[] array = new int[size];
             int i = 0;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 array[i++] = it.value();
             }
             return array;
         }

         default public IntCollection addAll(IntStream values) {
             for (IntIterator it = values.intIterator(); it.isValid(); it.advance()) {
                 add(it.value());
             }
             return this;
         }

     }

     static interface IntIterator {
         public int value() throws NoSuchElementException;

         public boolean advance();

         public boolean isValid();

     }

     static interface IntList extends IntReversableCollection {
         public abstract int get(int index);

         public abstract void addAt(int index, int value);

         public abstract void removeAt(int index);

         default public IntIterator intIterator() {
             return new IntIterator() {
                 private int at;
                 private boolean removed;

                 public int value() {
                     if (removed) {
                         throw new IllegalStateException();
                     }
                     return get(at);
                 }

                 public boolean advance() {
                     at++;
                     removed = false;
                     return isValid();
                 }

                 public boolean isValid() {
                     return !removed && at < size();
                 }

                 public void remove() {
                     removeAt(at);
                     at--;
                     removed = true;
                 }
             };
         }


         default public void add(int value) {
             addAt(size(), value);
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private InputReader.SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1) {
                 throw new InputMismatchException();
             }
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0) {
                     return -1;
                 }
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9') {
                     throw new InputMismatchException();
                 }
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public boolean isSpaceChar(int c) {
             if (filter != null) {
                 return filter.isSpaceChar(c);
             }
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public char readCharacter() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             return (char) c;
         }

         public interface SpaceCharFilter {
             public boolean isSpaceChar(int ch);

         }

     }

