package Dijkstra;


 public class ReadFile {
     public int caseNum;
     public List<List<String>> cases=new ArrayList<List<String>>();
     public ReadFile(String fileName){      
        try {
            Scanner in = new Scanner(new File(fileName));
            this.startRead(in);
