public class pB {
    String colors = "ROYGBV";
    String no = "IMPOSSIBLE";

    String solve() {
        for (int i = 1; i <= 5; i += 2) {
            if (a[i] > 0 && a[(i + 3) % 6] == a[i]) {
                int c = 0;
                for (int j = 0; j < 6; j++) {
                    if (a[j] > 0) {
                        c++;
                    }
                }
                if (c == 2) {
                    String s = "";
                    for (int j = 0; j < a[i]; j++) {
                        s += colors.charAt(i);
                        s += colors.charAt((i + 3) % 6);
                    }
                    return s;
                }
            }
            if (a[i] > 0 && a[(i + 3) % 6] <= a[i]) {
                return no;
            }
            a[(i + 3) % 6] -= a[i];
        }
        for (int i = 0; i <= 4; i += 2) {
            if (a[i] > a[(i + 2) % 6] + a[(i + 4) % 6]) {
                return no;
            }
        }
        String s = "";
        int p = -1;
        int f = -1;
        for (;;) {
            int q = -1;
            for (int i = 0; i <= 4; i += 2) {
                if (i == p) {
                    continue;
                }
                if (q == -1 || a[i] > a[q] || a[i] == a[q] && i == f) {
                    q = i;
                }
            }
            if (a[q] == 0) {
                break;
            }
            a[q]--;
            s += colors.charAt(q);
            if (p == -1) {
                f = q;
            }
            p = q;
        }
        for (int i = 1; i <= 5; i += 2) {
            char ci = colors.charAt(i);
            char co = colors.charAt((i + 3) % 6);
            String from = "" + co;
            String to = "" + co + ci + co;
            for (int j = 0; j < a[i]; j++) {
                s = s.replaceFirst(from, to);
            }
        }
        return s;
    }

    int[] a;

